contracts/AMLSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

/**
 * @title AMLSystem
 * @author AML Detection System
 * @notice An on-chain Anti-Money Laundering (AML) detection system.
 *         Registers users, tracks their verification/risk/blacklist status,
 *         accepts transaction records between addresses, automatically
 *         computes a 0-100 risk score for each transaction, and flags any
 *         transaction whose score meets or exceeds a configurable
 *         suspicious-activity threshold.
 *
 * @dev Security notes:
 *      - Follows checks-effects-interactions ordering throughout.
 *      - No raw ETH is moved by this contract; "amount" is a logged value
 *        used purely for risk scoring and record-keeping, so there is no
 *        reentrancy surface from external calls.
 *      - All admin-only entry points are gated by the `onlyOwner` modifier.
 *      - All numeric bounds (risk scores, thresholds) are validated on
 *        every write path, never trusted from calldata alone.
 *      - Solidity 0.8.19 has built-in overflow/underflow checks, so no
 *        SafeMath library is required.
 */
contract AMLSystem {
    // =========================================================================
    // Types
    // =========================================================================

    /// @notice Lifecycle status of a submitted transaction.
    enum TransactionStatus {
        Pending,   // 0 - reserved initial value, resolved before storage completes
        Approved,  // 1 - risk score below the suspicious threshold
        Flagged,   // 2 - risk score at/above the suspicious threshold
        Rejected   // 3 - blocked outright (e.g. blacklisted counterparty)
    }

    /// @notice A registered platform user.
    struct User {
        string name;
        uint256 riskScore;      // 0-100, higher = riskier
        bool isVerified;        // KYC / compliance verification status
        bool isBlacklisted;     // hard block from transacting
        bool isRegistered;      // existence flag, since structs zero-initialize
        uint256 registeredAt;   // block timestamp of registration
    }

    /// @notice A logged transaction between two addresses.
    struct Transaction {
        uint256 id;
        address sender;
        address receiver;
        uint256 amount;
        uint256 riskScore;      // 0-100, computed automatically at submission
        TransactionStatus status;
        uint256 timestamp;
    }

    // =========================================================================
    // State
    // =========================================================================

    /// @notice Contract owner / compliance administrator.
    address public owner;

    /// @notice Risk score (0-100) at or above which a transaction is auto-flagged.
    uint256 public suspiciousThreshold = 70;

    /// @notice All registered users, keyed by address.
    mapping(address => User) public users;

    /// @notice All submitted transactions, keyed by auto-incrementing id.
    mapping(uint256 => Transaction) public transactions;

    /// @notice Transaction ids associated with a given address (as sender or receiver).
    mapping(address => uint256[]) private userTransactionIds;

    /// @dev Running counter used to assign the next transaction id.
    uint256 private nextTransactionId;

    /// @dev Running count of transactions currently flagged as suspicious.
    uint256 private flaggedTransactionsCount;

    /// @dev Running count of total transactions submitted (== nextTransactionId, exposed via getter for clarity).
    uint256 private totalTransactionsCount;

    // =========================================================================
    // Events
    // =========================================================================

    /// @notice Emitted when a new user registers on the platform.
    event UserRegistered(address indexed user, string name, uint256 timestamp);

    /// @notice Emitted every time a transaction is submitted, regardless of outcome.
    event TransactionSubmitted(
        uint256 indexed id,
        address indexed sender,
        address indexed receiver,
        uint256 amount,
        uint256 riskScore,
        TransactionStatus status
    );

    /// @notice Emitted specifically when a transaction is flagged as suspicious.
    event TransactionFlagged(
        uint256 indexed id,
        address indexed sender,
        address indexed receiver,
        uint256 riskScore
    );

    /// @notice Emitted when an address is blacklisted.
    event UserBlacklisted(address indexed user, uint256 timestamp);

    /// @notice Emitted when the suspicious-activity threshold is changed.
    event ThresholdUpdated(uint256 oldThreshold, uint256 newThreshold);

    // --- Additional events (not strictly required, kept for completeness) ---

    /// @notice Emitted when a previously blacklisted address is cleared.
    event UserWhitelisted(address indexed user, uint256 timestamp);

    /// @notice Emitted when a user passes compliance verification.
    event UserVerified(address indexed user, uint256 timestamp);

    /// @notice Emitted when an admin manually overrides a user's risk score.
    event RiskScoreUpdated(address indexed user, uint256 oldScore, uint256 newScore);

    /// @notice Emitted when contract ownership changes.
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // =========================================================================
    // Modifiers
    // =========================================================================

    /// @dev Restricts a function to the contract owner (compliance admin).
    modifier onlyOwner() {
        require(msg.sender == owner, "AMLSystem: caller is not the owner");
        _;
    }

    /// @dev Ensures an address is registered before being referenced.
    modifier onlyRegistered(address account) {
        require(users[account].isRegistered, "AMLSystem: user is not registered");
        _;
    }

    /// @dev Blocks an action if the given address is blacklisted.
    modifier notBlacklisted(address account) {
        require(!users[account].isBlacklisted, "AMLSystem: address is blacklisted");
        _;
    }

    /// @dev Rejects the zero address, which can never be a valid participant.
    modifier validAddress(address account) {
        require(account != address(0), "AMLSystem: zero address not allowed");
        _;
    }

    // =========================================================================
    // Constructor
    // =========================================================================

    constructor() {
        owner = msg.sender;
    }

    // =========================================================================
    // User Registration
    // =========================================================================

    /**
     * @notice Register the caller as a platform user.
     * @dev New users start unverified, not blacklisted, with a neutral
     *      starting risk score of 50 (mid-scale, since there is no history
     *      yet to justify a low score).
     * @param name Display name for the user.
     */
    function registerUser(string calldata name) external validAddress(msg.sender) {
        require(!users[msg.sender].isRegistered, "AMLSystem: already registered");
        require(bytes(name).length > 0, "AMLSystem: name required");

        users[msg.sender] = User({
            name: name,
            riskScore: 50,
            isVerified: false,
            isBlacklisted: false,
            isRegistered: true,
            registeredAt: block.timestamp
        });

        emit UserRegistered(msg.sender, name, block.timestamp);
    }

    // =========================================================================
    // Transaction Management
    // =========================================================================

    /**
     * @notice Submit a transaction record between the caller and a receiver.
     * @dev No ETH is moved — `amount` is a logged value used for risk
     *      scoring. The transaction's risk score and status are computed
     *      automatically and immutably at submission time:
     *        - If the receiver is blacklisted, the transaction is Rejected
     *          outright regardless of score.
     *        - Otherwise, a 0-100 score is computed from the amount and
     *          both parties' standing; scores at/above the current
     *          suspicious threshold are Flagged, otherwise Approved.
     * @param receiver Address the funds/value are logically directed to.
     * @param amount Value of the transaction, for scoring/record purposes.
     * @return id The id assigned to the newly created transaction.
     */
    function submitTransaction(address receiver, uint256 amount)
        external
        validAddress(receiver)
        notBlacklisted(msg.sender)
        returns (uint256 id)
    {
        require(receiver != msg.sender, "AMLSystem: cannot transact with self");
        require(amount > 0, "AMLSystem: amount must be greater than zero");

        id = nextTransactionId;
        nextTransactionId += 1;
        totalTransactionsCount += 1;

        TransactionStatus status;
        uint256 riskScore;

        if (users[receiver].isBlacklisted) {
            // Hard block: never allow value logically flowing to a blacklisted party.
            status = TransactionStatus.Rejected;
            riskScore = 100;
        } else {
            riskScore = _calculateRiskScore(msg.sender, receiver, amount);
            status = riskScore >= suspiciousThreshold
                ? TransactionStatus.Flagged
                : TransactionStatus.Approved;
        }

        transactions[id] = Transaction({
            id: id,
            sender: msg.sender,
            receiver: receiver,
            amount: amount,
            riskScore: riskScore,
            status: status,
            timestamp: block.timestamp
        });

        userTransactionIds[msg.sender].push(id);
        userTransactionIds[receiver].push(id);

        emit TransactionSubmitted(id, msg.sender, receiver, amount, riskScore, status);

        if (status == TransactionStatus.Flagged) {
            flaggedTransactionsCount += 1;
            emit TransactionFlagged(id, msg.sender, receiver, riskScore);
        }

        return id;
    }

    /**
     * @dev Computes a deterministic 0-100 risk score for a prospective
     *      transaction. Pure function of on-chain state, so it can never
     *      be gamed by anything off-chain (like randomness or timestamps
     *      beyond what's already used for other purposes).
     *
     *      Scoring breakdown (weights sum to a maximum of 100):
     *        - Amount tier:            up to 40 points
     *        - Sender/receiver risk:   up to 50 points (avg of both, scaled)
     *        - Verification penalty:   up to 20 points (10 each if unverified)
     *      The raw sum is capped at 100.
     */
    function _calculateRiskScore(address sender, address receiver, uint256 amount)
        internal
        view
        returns (uint256 score)
    {
        // --- Amount tier: larger logged amounts are treated as riskier ---
        if (amount >= 100 ether) {
            score += 40;
        } else if (amount >= 50 ether) {
            score += 30;
        } else if (amount >= 10 ether) {
            score += 20;
        } else if (amount >= 1 ether) {
            score += 10;
        }

        // --- Counterparty risk: unregistered addresses are treated as medium-high risk ---
        uint256 senderRisk = users[sender].isRegistered ? users[sender].riskScore : 60;
        uint256 receiverRisk = users[receiver].isRegistered ? users[receiver].riskScore : 60;
        score += (senderRisk + receiverRisk) / 4; // contributes up to 50 points combined

        // --- Verification penalty: unverified parties add risk ---
        if (users[sender].isRegistered && !users[sender].isVerified) {
            score += 10;
        }
        if (users[receiver].isRegistered && !users[receiver].isVerified) {
            score += 10;
        }

        if (score > 100) {
            score = 100;
        }
    }

    // =========================================================================
    // Admin Functions
    // =========================================================================

    /**
     * @notice Update the risk-score threshold at/above which transactions are flagged.
     * @param newThreshold New threshold, must be between 0 and 100 inclusive.
     */
    function updateThreshold(uint256 newThreshold) external onlyOwner {
        require(newThreshold <= 100, "AMLSystem: threshold must be <= 100");
        uint256 oldThreshold = suspiciousThreshold;
        suspiciousThreshold = newThreshold;
        emit ThresholdUpdated(oldThreshold, newThreshold);
    }

    /**
     * @notice Mark a registered user as compliance-verified (e.g. passed KYC).
     * @param user Address to verify.
     */
    function verifyUser(address user) external onlyOwner onlyRegistered(user) {
        require(!users[user].isVerified, "AMLSystem: user already verified");
        users[user].isVerified = true;
        emit UserVerified(user, block.timestamp);
    }

    /**
     * @notice Blacklist an address, blocking it from submitting further transactions
     *         and rejecting any transaction directed to it.
     * @param user Address to blacklist.
     */
    function blacklistUser(address user) external onlyOwner validAddress(user) {
        require(!users[user].isBlacklisted, "AMLSystem: already blacklisted");
        users[user].isBlacklisted = true;
        emit UserBlacklisted(user, block.timestamp);
    }

    /**
     * @notice Remove an address from the blacklist (whitelist it again).
     * @param user Address to restore.
     */
    function whitelistUser(address user) external onlyOwner {
        require(users[user].isBlacklisted, "AMLSystem: address is not blacklisted");
        users[user].isBlacklisted = false;
        emit UserWhitelisted(user, block.timestamp);
    }

    /**
     * @notice Manually override a registered user's risk score.
     * @param user Address whose score is being updated.
     * @param newScore New risk score, must be between 0 and 100 inclusive.
     */
    function updateRiskScore(address user, uint256 newScore)
        external
        onlyOwner
        onlyRegistered(user)
    {
        require(newScore <= 100, "AMLSystem: risk score must be <= 100");
        uint256 oldScore = users[user].riskScore;
        users[user].riskScore = newScore;
        emit RiskScoreUpdated(user, oldScore, newScore);
    }

    /**
     * @notice Transfer contract ownership to a new admin address.
     * @param newOwner Address of the new owner.
     */
    function transferOwnership(address newOwner) external onlyOwner validAddress(newOwner) {
        address previousOwner = owner;
        owner = newOwner;
        emit OwnershipTransferred(previousOwner, newOwner);
    }

    // =========================================================================
    // View Functions
    // =========================================================================

    /**
     * @notice Get full details for a registered user.
     * @param user Address to look up.
     */
    function getUserDetails(address user)
        external
        view
        returns (
            string memory name,
            uint256 riskScore,
            bool isVerified,
            bool isBlacklisted,
            bool isRegistered,
            uint256 registeredAt
        )
    {
        User storage u = users[user];
        return (u.name, u.riskScore, u.isVerified, u.isBlacklisted, u.isRegistered, u.registeredAt);
    }

    /**
     * @notice Get full details for a single transaction.
     * @param id Transaction id to look up.
     */
    function getTransactionDetails(uint256 id)
        external
        view
        returns (
            address sender,
            address receiver,
            uint256 amount,
            uint256 riskScore,
            TransactionStatus status,
            uint256 timestamp
        )
    {
        require(id < nextTransactionId, "AMLSystem: transaction does not exist");
        Transaction storage t = transactions[id];
        return (t.sender, t.receiver, t.amount, t.riskScore, t.status, t.timestamp);
    }

    /**
     * @notice Total number of transactions ever submitted.
     */
    function getAllTransactionsCount() external view returns (uint256) {
        return totalTransactionsCount;
    }

    /**
     * @notice Total number of transactions currently flagged as suspicious.
     */
    function getFlaggedCount() external view returns (uint256) {
        return flaggedTransactionsCount;
    }

    /**
     * @notice Get all transaction ids involving a given address (as sender or receiver).
     * @param user Address to look up.
     */
    function getUserTransactions(address user) external view returns (uint256[] memory) {
        return userTransactionIds[user];
    }
}

contracts/PaymentProcessor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./UserRegistry.sol";
import "./FundRequest.sol";

/**
 * @title PaymentProcessor
 * @notice Handles a FUNDER's decision on a pending FundRequest: approve and
 *         pay (moving real ETH to the requester), or reject with a reason.
 *         Payments above `amlThreshold` are automatically flagged as
 *         suspicious, on both the Payment record here and the underlying
 *         FundRequest.
 *
 * @dev Uses COMPOSITION with both UserRegistry and FundRequest (holds their
 *      addresses, doesn't inherit them). Because of this, FundRequest.sol's
 *      updateRequestAsApproved / updateRequestAsCompleted /
 *      updateRequestAsRejected / flagSuspicious functions are `external`,
 *      gated by an `onlyPaymentProcessor` modifier there. After deploying
 *      this contract, you MUST call `fundRequest.setPaymentProcessor(address(this))`
 *      (as the FundRequest admin) before approveAndPay/rejectRequest will work —
 *      otherwise every call here reverts when it tries to update FundRequest.
 *
 * @dev On `txHash`: Solidity has no way to read the hash of the very
 *      transaction currently executing — that hash only exists once the
 *      transaction is fully signed and broadcast, which happens outside the
 *      EVM. So `Payment.txHash` below stores a deterministic **synthetic**
 *      reference hash (derived from the payment's own fields), not the
 *      real on-chain transaction hash. If you need the real transaction
 *      hash for display purposes, capture it off-chain from the
 *      transaction receipt (e.g. `tx.hash` in ethers.js after
 *      `approveAndPay(...)` is mined) and store/show it in the frontend.
 */
contract PaymentProcessor {
    // =========================================================================
    // Types
    // =========================================================================

    /// @notice A completed payment record.
    struct Payment {
        uint256 paymentId;
        uint256 requestId;
        address funder;
        address requester;
        uint256 amount;
        uint256 timestamp;
        bytes32 txHash; // synthetic reference hash — see contract-level @dev note
        bool isSuspicious;
    }

    // =========================================================================
    // State
    // =========================================================================

    /// @notice Running counter used to assign each payment a unique id.
    uint256 public paymentCounter;

    /// @notice Payments strictly above this amount (in wei) are flagged suspicious.
    uint256 public amlThreshold = 5 ether;

    /// @notice All payments, keyed by id.
    mapping(uint256 => Payment) public payments;

    /// @notice Payment ids involving each address (as funder or requester).
    mapping(address => uint256[]) public userPayments;

    /// @notice The UserRegistry this contract checks roles/blacklist status against.
    UserRegistry public userRegistry;

    /// @notice The FundRequest contract whose requests this contract processes.
    FundRequest public fundRequest;

    /// @notice The account that deployed this contract; authorized to change amlThreshold.
    address public admin;

    // =========================================================================
    // Events
    // =========================================================================

    event PaymentCompleted(
        uint256 indexed paymentId,
        uint256 indexed requestId,
        address funder,
        address requester,
        uint256 amount
    );
    event PaymentFlagged(uint256 indexed paymentId, uint256 amount);
    event ThresholdUpdated(uint256 newThreshold);
    event ApprovalRequiresAdmin(uint256 indexed requestId, uint256 amount);

    // =========================================================================
    // Modifiers
    // =========================================================================

    /// @dev Restricts a function to the contract admin (deployer).
    modifier onlyAdmin() {
        require(msg.sender == admin, "PaymentProcessor: caller is not the admin");
        _;
    }

    /// @dev Ensures the caller has registered in the UserRegistry.
    modifier onlyRegistered() {
        require(userRegistry.isUserRegistered(msg.sender), "PaymentProcessor: caller is not registered");
        _;
    }

    /// @dev Ensures the caller is registered with the FUNDER role.
    modifier onlyFunder() {
        require(
            userRegistry.getUserRole(msg.sender) == UserRegistry.UserRole.FUNDER,
            "PaymentProcessor: caller is not a FUNDER"
        );
        _;
    }

    /// @dev Blocks an action if the given address is blacklisted in UserRegistry.
    modifier notBlacklisted(address _addr) {
        require(!userRegistry.getUserInfo(_addr).isBlacklisted, "PaymentProcessor: address is blacklisted");
        _;
    }

    // =========================================================================
    // Constructor
    // =========================================================================

    /**
     * @param _userRegistry Address of an already-deployed UserRegistry.
     * @param _fundRequest Address of an already-deployed FundRequest.
     */
    constructor(address _userRegistry, address _fundRequest) {
        userRegistry = UserRegistry(_userRegistry);
        fundRequest = FundRequest(_fundRequest);
        admin = msg.sender;
    }

    // =========================================================================
    // Funder actions
    // =========================================================================

    /**
     * @notice Approve a pending request and pay it in the same transaction.
     *         The caller must send exactly the requested amount as msg.value.
     * @param _requestId The request to approve and pay.
     */
    function approveAndPay(uint256 _requestId)
        external
        payable
        onlyRegistered
        onlyFunder
        notBlacklisted(msg.sender)
    {
        FundRequest.FundRequest memory req = fundRequest.getRequest(_requestId);

        require(req.status == FundRequest.RequestStatus.PENDING, "PaymentProcessor: request is not pending");
        require(!userRegistry.getUserInfo(req.requester).isBlacklisted, "PaymentProcessor: requester is blacklisted");
        require(msg.value == req.amount, "PaymentProcessor: sent value does not match requested amount");

        // Note on "ensure funder has sufficient balance": Ethereum enforces
        // this at the transaction level automatically — a transaction that
        // sends more ETH than the sender holds is rejected by the network
        // before this function ever runs, so no additional balance check is
        // needed (or even meaningfully possible) here.

        bool suspicious = _isSuspicious(msg.value);
        if (suspicious) {
            emit ApprovalRequiresAdmin(_requestId, msg.value);
        }

        // Mark the request APPROVED (with this funder) before processing
        // payment, so its state reflects the decision even if something
        // below were to revert.
        fundRequest.updateRequestAsApproved(_requestId, msg.sender);

        _processPayment(_requestId, req.requester, msg.value, suspicious);
    }

    /**
     * @notice Reject a pending request with a reason. No funds move.
     * @param _requestId The request to reject.
     * @param _reason Human-readable rejection reason.
     */
    function rejectRequest(uint256 _requestId, string memory _reason)
        external
        onlyRegistered
        onlyFunder
    {
        FundRequest.FundRequest memory req = fundRequest.getRequest(_requestId);
        require(req.status == FundRequest.RequestStatus.PENDING, "PaymentProcessor: request is not pending");

        fundRequest.updateRequestAsRejected(_requestId, msg.sender, _reason);
    }

    // =========================================================================
    // Admin actions
    // =========================================================================

    /**
     * @notice Update the amount above which payments are auto-flagged suspicious.
     * @param _newThreshold New threshold, in wei.
     */
    function setThreshold(uint256 _newThreshold) external onlyAdmin {
        amlThreshold = _newThreshold;
        emit ThresholdUpdated(_newThreshold);
    }

    // =========================================================================
    // Views
    // =========================================================================

    /**
     * @notice Get full details for a single payment.
     * @param _paymentId The payment to look up.
     */
    function getPayment(uint256 _paymentId) external view returns (Payment memory) {
        require(_paymentId < paymentCounter, "PaymentProcessor: payment does not exist");
        return payments[_paymentId];
    }

    /**
     * @notice Get all payment ids involving a given address (as funder or requester).
     * @param _user Address to look up.
     */
    function getPaymentsByUser(address _user) external view returns (uint256[] memory) {
        return userPayments[_user];
    }

    /// @notice Total number of payments ever processed.
    function getPaymentCount() external view returns (uint256) {
        return paymentCounter;
    }

    /// @notice Current AML suspicious-amount threshold, in wei.
    function getThreshold() external view returns (uint256) {
        return amlThreshold;
    }

    // =========================================================================
    // Internal helpers
    // =========================================================================

    /**
     * @dev Records the Payment, marks the FundRequest COMPLETED, flags it
     *      suspicious if applicable, and transfers the ETH to the requester.
     *      State is updated before the external ETH transfer
     *      (checks-effects-interactions) to guard against reentrancy.
     */
    function _processPayment(
        uint256 _requestId,
        address _requester,
        uint256 _amount,
        bool _suspicious
    ) internal {
        uint256 paymentId = paymentCounter++;

        bytes32 syntheticTxHash = keccak256(
            abi.encodePacked(paymentId, _requestId, msg.sender, _requester, _amount, block.timestamp)
        );

        payments[paymentId] = Payment({
            paymentId: paymentId,
            requestId: _requestId,
            funder: msg.sender,
            requester: _requester,
            amount: _amount,
            timestamp: block.timestamp,
            txHash: syntheticTxHash,
            isSuspicious: _suspicious
        });

        userPayments[msg.sender].push(paymentId);
        userPayments[_requester].push(paymentId);

        // Effects before interaction: update FundRequest and emit events
        // BEFORE sending ETH out.
        fundRequest.updateRequestAsCompleted(_requestId);

        if (_suspicious) {
            fundRequest.flagSuspicious(_requestId);
            emit PaymentFlagged(paymentId, _amount);
        }

        emit PaymentCompleted(paymentId, _requestId, msg.sender, _requester, _amount);

        // Interaction: send the ETH to the requester last.
        (bool sent, ) = payable(_requester).call{value: _amount}("");
        require(sent, "PaymentProcessor: ETH transfer failed");
    }

    /// @dev A payment is suspicious if it strictly exceeds the current threshold.
    function _isSuspicious(uint256 _amount) internal view returns (bool) {
        return _amount > amlThreshold;
    }
}

contracts/UserRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title UserRegistry
 * @notice Manages user registration and role assignment for the AML system.
 *         Three roles exist: REQUESTER (asks for funds), FUNDER (approves
 *         and pays requests), and ADMIN (compliance oversight). Blacklisted
 *         addresses are blocked from registering or updating their profile.
 *
 * @dev incrementUserRequests() and incrementUserPayments() are declared
 *      `internal` exactly as specified, which means they can only be called
 *      from within this contract or from a contract that INHERITS it. If
 *      FundRequest.sol / PaymentProcessor.sol are meant to update these
 *      counters, they should be written as `contract FundRequest is
 *      UserRegistry { ... }` (inheritance), not as separate contracts that
 *      merely hold this contract's address. If composition (a separate,
 *      already-deployed UserRegistry referenced by address) is preferred
 *      instead, these two functions would need to become `external` with
 *      their own access control (e.g. an `onlyAuthorizedContract` modifier)
 *      — flagging this now so the two designs don't end up incompatible.
 */
contract UserRegistry {
    // =========================================================================
    // Types
    // =========================================================================

    /// @notice The three participant roles in the system, plus a default NONE.
    enum UserRole {
        NONE,       // 0 - default/unset, not a valid registration role
        REQUESTER,  // 1 - asks for funds
        FUNDER,     // 2 - approves and pays requests
        ADMIN       // 3 - compliance oversight
    }

    /// @notice A registered user's full profile.
    struct User {
        string name;
        UserRole role;
        address walletAddress;
        uint256 annualIncome;      // in wei
        bool isRegistered;
        bool isBlacklisted;
        uint256 registrationDate;
        uint256 totalRequests;
        uint256 totalPayments;
    }

    // =========================================================================
    // State
    // =========================================================================

    /// @notice The account that deployed this contract; the compliance admin.
    address public admin;

    /// @notice Running count of all registered users.
    uint256 public totalUsers;

    /// @notice Full profile for each registered address.
    mapping(address => User) public users;

    /// @notice Quick existence check, kept separate from `users` so a
    ///         zero-initialized (never-registered) User struct can never be
    ///         mistaken for a real one.
    mapping(address => bool) public registeredAddresses;

    // =========================================================================
    // Events
    // =========================================================================

    /// @notice Emitted when a brand-new address registers.
    event UserRegistered(address indexed user, string name, UserRole role);

    /// @notice Emitted when an existing user updates their profile.
    event UserUpdated(address indexed user, string name);

    /// @notice Emitted when the admin blacklists an address.
    event UserBlacklisted(address indexed user);

    /// @notice Emitted when the admin clears a blacklisted address.
    event UserWhitelisted(address indexed user);

    // =========================================================================
    // Modifiers
    // =========================================================================

    /// @dev Restricts a function to the contract admin (deployer).
    modifier onlyAdmin() {
        require(msg.sender == admin, "UserRegistry: caller is not the admin");
        _;
    }

    /// @dev Ensures the caller has registered before acting on their own profile.
    modifier onlyRegistered() {
        require(registeredAddresses[msg.sender], "UserRegistry: caller is not registered");
        _;
    }

    /// @dev Blocks an action if the given address is blacklisted. Safe to
    ///      call even for an address that isn't registered yet (a
    ///      never-registered address defaults to isBlacklisted == false).
    modifier notBlacklisted(address _user) {
        require(!users[_user].isBlacklisted, "UserRegistry: address is blacklisted");
        _;
    }

    // =========================================================================
    // Constructor
    // =========================================================================

    /// @notice Deploys the registry with the deployer set as admin.
    constructor() {
        admin = msg.sender;
    }

    // =========================================================================
    // Registration
    // =========================================================================

    /**
     * @notice Register the caller as a new user with a chosen role.
     * @param _name Display name for the user. Must be non-empty.
     * @param _role One of REQUESTER, FUNDER, or ADMIN — NONE is rejected.
     * @param _annualIncome Self-reported annual income, in wei, used
     *        elsewhere in the system for risk/eligibility checks.
     */
    function registerUser(
        string calldata _name,
        UserRole _role,
        uint256 _annualIncome
    ) external notBlacklisted(msg.sender) {
        require(!registeredAddresses[msg.sender], "UserRegistry: already registered");
        require(bytes(_name).length > 0, "UserRegistry: name required");
        require(_role != UserRole.NONE, "UserRegistry: role required");

        users[msg.sender] = User({
            name: _name,
            role: _role,
            walletAddress: msg.sender,
            annualIncome: _annualIncome,
            isRegistered: true,
            isBlacklisted: false,
            registrationDate: block.timestamp,
            totalRequests: 0,
            totalPayments: 0
        });

        registeredAddresses[msg.sender] = true;
        totalUsers += 1;

        emit UserRegistered(msg.sender, _name, _role);
    }

    /**
     * @notice Update the caller's own name and/or annual income. Role and
     *         wallet address are immutable once registered.
     * @param _name New display name. Must be non-empty.
     * @param _annualIncome New self-reported annual income, in wei.
     */
    function updateUserProfile(string calldata _name, uint256 _annualIncome)
        external
        onlyRegistered
        notBlacklisted(msg.sender)
    {
        require(bytes(_name).length > 0, "UserRegistry: name required");

        User storage u = users[msg.sender];
        u.name = _name;
        u.annualIncome = _annualIncome;

        emit UserUpdated(msg.sender, _name);
    }

    // =========================================================================
    // Admin actions
    // =========================================================================

    /**
     * @notice Blacklist a registered address, blocking further registration
     *         updates. Other contracts in the system (FundRequest,
     *         PaymentProcessor) are expected to also check isBlacklisted
     *         before allowing requests or payments involving this address.
     * @param _user Address to blacklist.
     */
    function blacklistUser(address _user) external onlyAdmin {
        require(registeredAddresses[_user], "UserRegistry: user not registered");
        require(!users[_user].isBlacklisted, "UserRegistry: already blacklisted");
        users[_user].isBlacklisted = true;
        emit UserBlacklisted(_user);
    }

    /**
     * @notice Remove an address from the blacklist.
     * @param _user Address to restore.
     */
    function whitelistUser(address _user) external onlyAdmin {
        require(users[_user].isBlacklisted, "UserRegistry: address is not blacklisted");
        users[_user].isBlacklisted = false;
        emit UserWhitelisted(_user);
    }

    // =========================================================================
    // Views
    // =========================================================================

    /**
     * @notice Get the full profile for an address.
     * @param _user Address to look up.
     * @return The User struct (zero-initialized if never registered).
     */
    function getUserInfo(address _user) external view returns (User memory) {
        return users[_user];
    }

    /**
     * @notice Check whether an address has registered.
     * @param _user Address to check.
     */
    function isUserRegistered(address _user) external view returns (bool) {
        return registeredAddresses[_user];
    }

    /**
     * @notice Get an address's assigned role.
     * @param _user Address to check.
     * @return NONE if never registered, otherwise their chosen role.
     */
    function getUserRole(address _user) external view returns (UserRole) {
        return users[_user].role;
    }

    /// @notice Total number of addresses that have ever registered.
    function getTotalUsers() external view returns (uint256) {
        return totalUsers;
    }

    // =========================================================================
    // Internal helpers
    // =========================================================================
    // NOTE: internal as specified — only callable from this contract or a
    // contract that inherits it. See the contract-level @dev comment above
    // for the inheritance-vs-composition implication.

    /// @dev Increment a user's lifetime request count. Called by inheriting
    ///      contracts (e.g. FundRequest) whenever that user files a request.
    function incrementUserRequests(address _user) internal {
        users[_user].totalRequests += 1;
    }

    /// @dev Increment a user's lifetime payment count. Called by inheriting
    ///      contracts (e.g. PaymentProcessor) whenever that user completes a payment.
    function incrementUserPayments(address _user) internal {
        users[_user].totalPayments += 1;
    }
}

