// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./UserRegistry.sol";

/**
 * @title FundRequest
 * @notice Handles money requests filed by REQUESTER-role users against the
 *         UserRegistry. A request moves through PENDING -> APPROVED ->
 *         COMPLETED (the happy path), or PENDING -> REJECTED / CANCELLED.
 *
 * @dev This contract uses COMPOSITION with UserRegistry (holds its address
 *      and calls its external/public functions), not inheritance. Four
 *      functions below — updateRequestAsApproved, updateRequestAsCompleted,
 *      updateRequestAsRejected, and flagSuspicious — are declared `internal`
 *      exactly as specified, with comments noting they're "called by
 *      PaymentProcessor". Because this contract does NOT inherit
 *      PaymentProcessor (composition is used instead), a separately
 *      deployed PaymentProcessor contract holding this contract's address
 *      CANNOT actually call internal functions on it — internal visibility
 *      only permits calls from within this same contract, or from a
 *      contract that inherits it.
 *
 *      This is flagged clearly rather than silently worked around: if
 *      PaymentProcessor.sol is meant to update request status via a held
 *      address reference (matching the composition pattern used here for
 *      UserRegistry), these four functions need to become `external` with
 *      access control (e.g. an `onlyPaymentProcessor` modifier checking
 *      against a stored, admin-settable PaymentProcessor address).
 *      Alternatively, PaymentProcessor.sol could inherit FundRequest
 *      (`contract PaymentProcessor is FundRequest`) to use them as-is.
 *      Confirm which approach is wanted before PaymentProcessor.sol is
 *      built, since it changes this contract's visibility.
 */
contract FundRequest {
    // =========================================================================
    // Types
    // =========================================================================

    /// @notice Lifecycle status of a fund request.
    enum RequestStatus {
        PENDING,
        APPROVED,
        REJECTED,
        COMPLETED,
        CANCELLED
    }

    /// @notice Self-reported urgency level, informational only.
    enum Urgency {
        LOW,
        MEDIUM,
        HIGH
    }

    /**
     * @notice A single fund request.
     * @dev Named identically to the enclosing contract, per spec. Solidity
     *      permits this (it only emits a harmless "shadows an existing
     *      declaration" compiler warning), but it does mean other contracts
     *      referencing this type externally must write the fully-qualified
     *      form `FundRequest.FundRequest` rather than just `FundRequest`.
     */
    struct FundRequest {
        uint256 id;
        address requester;
        address funder;             // address(0) if not yet assigned
        uint256 amount;             // in wei
        string purpose;
        Urgency urgency;
        RequestStatus status;
        uint256 createdAt;
        uint256 processedAt;
        string rejectionReason;
        bool isSuspicious;
    }

    // =========================================================================
    // State
    // =========================================================================

    /// @notice Running counter used to assign each request a unique id.
    uint256 public requestCounter;

    /// @notice All requests, keyed by id.
    mapping(uint256 => FundRequest) public requests;

    /// @notice Request ids filed by each address.
    mapping(address => uint256[]) public userRequests;

    /// @notice Ids of all requests currently in PENDING status.
    uint256[] public pendingRequestIds;

    /// @notice The UserRegistry this contract checks roles/registration against.
    UserRegistry public userRegistry;

    // =========================================================================
    // Events
    // =========================================================================

    event RequestCreated(uint256 indexed id, address indexed requester, uint256 amount, string purpose);
    event RequestApproved(uint256 indexed id, address indexed funder);
    event RequestRejected(uint256 indexed id, address indexed funder, string reason);
    event RequestCompleted(uint256 indexed id, uint256 amount);
    event RequestCancelled(uint256 indexed id);
    event SuspiciousRequestFlagged(uint256 indexed id, uint256 amount);

    // =========================================================================
    // Modifiers
    // =========================================================================

    /// @dev Ensures the caller has registered in the UserRegistry.
    modifier onlyRegistered() {
        require(userRegistry.isUserRegistered(msg.sender), "FundRequest: caller is not registered");
        _;
    }

    /// @dev Ensures the caller is the original requester of the given request.
    modifier onlyRequester(uint256 _requestId) {
        require(requests[_requestId].requester == msg.sender, "FundRequest: caller is not the requester");
        _;
    }

    /// @dev Ensures the given request is still PENDING.
    modifier onlyPending(uint256 _requestId) {
        require(requests[_requestId].status == RequestStatus.PENDING, "FundRequest: request is not pending");
        _;
    }

    // =========================================================================
    // Constructor
    // =========================================================================

    /**
     * @param _userRegistryAddress Address of an already-deployed UserRegistry.
     */
    constructor(address _userRegistryAddress) {
        userRegistry = UserRegistry(_userRegistryAddress);
    }

    // =========================================================================
    // Requester actions
    // =========================================================================

    /**
     * @notice File a new fund request. Caller must be registered with the
     *         REQUESTER role in UserRegistry.
     * @param _amount Amount requested, in wei. Must be greater than zero.
     * @param _purpose Human-readable reason for the request. Must be non-empty.
     * @param _urgency Self-reported urgency level.
     * @return requestId The id assigned to the new request.
     */
    function createRequest(uint256 _amount, string memory _purpose, Urgency _urgency)
        external
        onlyRegistered
        returns (uint256 requestId)
    {
        require(
            userRegistry.getUserRole(msg.sender) == UserRegistry.UserRole.REQUESTER,
            "FundRequest: caller is not a REQUESTER"
        );
        require(_amount > 0, "FundRequest: amount must be greater than zero");
        require(bytes(_purpose).length > 0, "FundRequest: purpose required");

        requestId = requestCounter++;

        requests[requestId] = FundRequest({
            id: requestId,
            requester: msg.sender,
            funder: address(0),
            amount: _amount,
            purpose: _purpose,
            urgency: _urgency,
            status: RequestStatus.PENDING,
            createdAt: block.timestamp,
            processedAt: 0,
            rejectionReason: "",
            isSuspicious: false
        });

        userRequests[msg.sender].push(requestId);
        pendingRequestIds.push(requestId);

        emit RequestCreated(requestId, msg.sender, _amount, _purpose);
    }

    /**
     * @notice Cancel the caller's own request. Only possible while it's
     *         still PENDING — once a funder has acted on it, it can no
     *         longer be cancelled.
     * @param _requestId The request to cancel.
     */
    function cancelRequest(uint256 _requestId)
        external
        onlyRequester(_requestId)
        onlyPending(_requestId)
    {
        requests[_requestId].status = RequestStatus.CANCELLED;
        requests[_requestId].processedAt = block.timestamp;

        _removePendingRequest(_requestId);

        emit RequestCancelled(_requestId);
    }

    // =========================================================================
    // Views
    // =========================================================================

    /**
     * @notice Get full details for a single request.
     * @param _requestId The request to look up.
     */
    function getRequest(uint256 _requestId) external view returns (FundRequest memory) {
        require(_requestId < requestCounter, "FundRequest: request does not exist");
        return requests[_requestId];
    }

    /**
     * @notice Get all request ids filed by a given address.
     * @param _user Address to look up.
     */
    function getRequestsByUser(address _user) external view returns (uint256[] memory) {
        return userRequests[_user];
    }

    /// @notice Get the ids of all requests currently awaiting a decision.
    function getPendingRequests() external view returns (uint256[] memory) {
        return pendingRequestIds;
    }

    /// @notice Total number of requests ever created.
    function getRequestsCount() external view returns (uint256) {
        return requestCounter;
    }

    // =========================================================================
    // Internal helpers
    // =========================================================================
    // NOTE: internal as specified — see the contract-level @dev comment above
    // regarding the composition-vs-inheritance implication for PaymentProcessor.

    /// @dev Generic status setter, used internally by the more specific
    ///      update functions below.
    function _updateStatus(uint256 _requestId, RequestStatus _status) internal {
        requests[_requestId].status = _status;
    }

    /// @dev Removes a request id from the pending list via swap-and-pop.
    ///      No-ops silently if the id isn't found (already removed).
    function _removePendingRequest(uint256 _requestId) internal {
        uint256 length = pendingRequestIds.length;
        for (uint256 i = 0; i < length; i++) {
            if (pendingRequestIds[i] == _requestId) {
                pendingRequestIds[i] = pendingRequestIds[length - 1];
                pendingRequestIds.pop();
                break;
            }
        }
    }

    /// @dev Marks a request APPROVED and assigns the funder who approved it.
    ///      Intended to be called by PaymentProcessor — see the
    ///      contract-level @dev note about the internal/composition conflict.
    function updateRequestAsApproved(uint256 _requestId, address _funder) internal {
        requests[_requestId].funder = _funder;
        requests[_requestId].processedAt = block.timestamp;
        _updateStatus(_requestId, RequestStatus.APPROVED);
        _removePendingRequest(_requestId);

        emit RequestApproved(_requestId, _funder);
    }

    /// @dev Marks a request COMPLETED once payment has actually settled.
    ///      Intended to be called by PaymentProcessor — see the
    ///      contract-level @dev note about the internal/composition conflict.
    function updateRequestAsCompleted(uint256 _requestId) internal {
        _updateStatus(_requestId, RequestStatus.COMPLETED);

        emit RequestCompleted(_requestId, requests[_requestId].amount);
    }

    /// @dev Marks a request REJECTED with a reason.
    ///      Intended to be called by PaymentProcessor — see the
    ///      contract-level @dev note about the internal/composition conflict.
    function updateRequestAsRejected(uint256 _requestId, address _funder, string memory _reason) internal {
        requests[_requestId].funder = _funder;
        requests[_requestId].processedAt = block.timestamp;
        requests[_requestId].rejectionReason = _reason;
        _updateStatus(_requestId, RequestStatus.REJECTED);
        _removePendingRequest(_requestId);

        emit RequestRejected(_requestId, _funder, _reason);
    }

    /// @dev Flags a request as suspicious for compliance review. No automatic
    ///      trigger condition is wired in here (e.g. an amount threshold) —
    ///      the spec didn't define one, so this is exposed for a caller
    ///      (inheriting contract) to invoke under whatever rule it implements.
    function flagSuspicious(uint256 _requestId) internal {
        requests[_requestId].isSuspicious = true;

        emit SuspiciousRequestFlagged(_requestId, requests[_requestId].amount);
    }
}
